from pathlib import Path
import sys

root=Path(sys.argv[1]); p=root/'public'/'app.js'; cssp=root/'public'/'styles.css'; swp=root/'public'/'sw.js'
s=p.read_text()

def rep(old,new,label):
 global s
 if old not in s: raise SystemExit('APP trecho não encontrado: '+label)
 s=s.replace(old,new,1)

# Ícone filtro + estado local apenas temporário para filtros de tela.
rep("bell:'<path d=\"M18 8", "filter:'<path d=\"M4 6h16M7 12h10M10 18h4\"/>',bell:'<path d=\"M18 8", 'icone filtro')
rep("turnstileWidget:null};", "turnstileWidget:null,filters:{}};", 'estado filtros')

# Sync econômico: 8s -> 2min + atualização imediata ao voltar/recuperar conexão.
old="function startSync(){clearInterval(versionPoll);versionPoll=setInterval(async()=>{if(!state.data||document.hidden)return;try{const v=await api('/api/version');if(Number(v.version)!==Number(state.data.profile.data_version)){state.data=await api('/api/bootstrap');renderApp(false);toast('Ritmo sincronizado.')}}catch{}},8000)}"
new="async function syncIfNeeded(showToast=false){if(!state.data||document.hidden||!navigator.onLine)return;try{const v=await api('/api/version');if(Number(v.version)!==Number(state.data.profile.data_version)){state.data=await api('/api/bootstrap');applyTheme(state.data.settings?.theme||'system');renderApp(false);if(showToast)toast('Ritmo sincronizado.')}}catch{}}function startSync(){clearInterval(versionPoll);versionPoll=setInterval(()=>syncIfNeeded(false),120000)}"
rep(old,new,'sync econômico')

# Barra inferior personalizável na nuvem: Início e Mais fixos, 3 do meio.
old="const bottom=[['home','Início','home'],['expenses','Movimentações','wallet'],['debts','Dívidas','wallet'],['goals','Metas','target'],['settings','Mais','menu']];"
new="""const shortcutCatalog={expenses:['expenses','Movimentações','wallet'],debts:['debts','Dívidas','wallet'],goals:['goals','Metas','target'],calendar:['calendar','Calendário','calendar'],insights:['insights','Insights','spark'],settings:['settings','Ajustes','gear']};
const defaultShortcuts=['expenses','debts','goals'];
function mobileShortcutKeys(){let raw=state.data?.settings?.mobile_shortcuts;try{if(typeof raw==='string')raw=JSON.parse(raw)}catch{};const src=Array.isArray(raw)?raw:defaultShortcuts,a=[];for(const k of src)if(shortcutCatalog[k]&&!a.includes(k))a.push(k);for(const k of defaultShortcuts)if(a.length<3&&!a.includes(k))a.push(k);return a.slice(0,3)}
function mobileBottom(){return [['home','Início','home'],...mobileShortcutKeys().map(k=>shortcutCatalog[k]),['more','Mais','menu']]}"""
rep(old,new,'bottom personalizável')
rep("${bottom.map(n=>`<button data-page=\"${n[0]}\" class=\"${state.page===n[0]||(n[0]==='expenses'&&state.page==='income')?'active':''}\">", "${mobileBottom().map(n=>`<button data-page=\"${n[0]}\" class=\"tone-${n[0]} ${state.page===n[0]||(n[0]==='expenses'&&state.page==='income')||(n[0]==='more'&&['calendar','insights','settings','profile','shortcuts'].includes(state.page))?'active':''}\">", 'render bottom')
rep("${nav.map(n=>`<button data-page=\"${n[0]}\" class=\"${state.page===n[0]?'active':''}\">", "${nav.map(n=>`<button data-page=\"${n[0]}\" class=\"tone-${n[0]} ${state.page===n[0]?'active':''}\">", 'nav cores')

helpers=r'''
function defaultFilter(){return {from:'',to:'',month:'',status:'all'}}
function getFilter(type){return state.filters[type]||defaultFilter()}
function filterDate(x,type){if(type==='income'||type==='expense')return x.date||'';if(type==='debt')return x.due_date||x.start_date||'';if(type==='goal')return x.deadline||'';return ''}
function filterItems(items,type){const f=getFilter(type);return items.filter(x=>{const d=filterDate(x,type);if(f.month&&(!d||!d.startsWith(f.month)))return false;if(f.from&&(!d||d<f.from))return false;if(f.to&&(!d||d>f.to))return false;if(f.status&&f.status!=='all'){if(type==='expense'){const overdue=x.status!=='pago'&&x.due_date&&x.due_date<isoToday();if(f.status==='paid'&&x.status!=='pago')return false;if(f.status==='pending'&&(x.status==='pago'||overdue))return false;if(f.status==='overdue'&&!overdue)return false}if(type==='debt'){if(f.status==='active'&&x.status==='quitada')return false;if(f.status==='done'&&x.status!=='quitada')return false}if(type==='goal'){const done=Number(x.current_amount||0)>=Number(x.target_amount||0);if(f.status==='active'&&done)return false;if(f.status==='done'&&!done)return false}}return true})}
function filterActive(type){const f=getFilter(type);return !!(f.from||f.to||f.month||(f.status&&f.status!=='all'))}
function filterAction(type){return `<button class="icon-btn head-filter-btn ${filterActive(type)?'active':''}" data-filter="${type}" aria-label="Filtrar" title="Filtrar">${ic('filter',19)}${filterActive(type)?'<span class="filter-dot"></span>':''}</button>`}
function listAction(filterType,newType,label){return innerWidth<=760?filterAction(filterType):`<button class="btn btn-primary" data-new="${newType}">${ic('plus',17)} ${label}</button>`}
function filterSummary(type,items){return filterActive(type)?`<div class="filter-summary"><span>${items.length} resultado(s) com filtro aplicado</span><button type="button" data-filter-clear="${type}">Limpar</button></div>`:''}
function filterStatusOptions(type,value){let rows=[['all','Todos']];if(type==='expense')rows.push(['paid','Pagas'],['pending','Pendentes'],['overdue','Vencidas']);if(type==='debt')rows.push(['active','Ativas'],['done','Quitadas']);if(type==='goal')rows.push(['active','Em andamento'],['done','Concluídas']);if(rows.length===1)return '';return `<label class="field full">Status<select id="filterStatus">${rows.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></label>`}
function filterModalHtml(type){const f=getFilter(type),title={income:'Entradas',expense:'Saídas',debt:'Dívidas',goal:'Metas'}[type]||'Itens';return `<div class="modal-wrap" id="modalWrap"><div class="modal filter-modal"><div class="modal-head"><div><h3>Filtrar ${title}</h3><div class="meta">Escolha um período rápido, um mês ou um intervalo personalizado.</div></div><button class="close" id="modalClose">×</button></div><div class="filter-section"><strong>Período rápido</strong><div class="filter-chips"><button type="button" data-filter-days="7">Últimos 7 dias</button><button type="button" data-filter-days="15">Últimos 15 dias</button><button type="button" data-filter-days="30">Últimos 30 dias</button></div></div><div class="form-grid filter-grid"><label class="field full">Escolher mês<input id="filterMonth" type="month" value="${esc(f.month)}"></label><label class="field">Data inicial<input id="filterFrom" type="date" value="${esc(f.from)}"></label><label class="field">Data final<input id="filterTo" type="date" value="${esc(f.to)}"></label>${filterStatusOptions(type,f.status)}<div class="full filter-actions"><button type="button" class="btn btn-secondary" id="clearFilter">Limpar filtros</button><button type="button" class="btn btn-primary" id="applyFilter">Aplicar filtros</button></div></div></div></div>`}
function dateIsoLocal(d){const x=new Date(d);x.setMinutes(x.getMinutes()-x.getTimezoneOffset());return x.toISOString().slice(0,10)}
function seenNotificationIds(){let raw=state.data?.settings?.seen_notifications;try{if(typeof raw==='string')raw=JSON.parse(raw)}catch{};return Array.isArray(raw)?raw:[]}
'''
rep('function notifications(){',helpers+'\nfunction notifications(){','helpers')

# Notificações vistas agora são fonte de nuvem, não localStorage.
rep("const seen=new Set(JSON.parse(localStorage.getItem(`ritmo:seen:${state.data.profile.id}`)||'[]'));", "const seen=new Set(seenNotificationIds());", 'unread seen cloud')
rep("const list=notifications(),seen=new Set(JSON.parse(localStorage.getItem(`ritmo:seen:${state.data.profile.id}`)||'[]'));", "const list=notifications(),seen=new Set(seenNotificationIds());", 'notifications seen cloud')
rep("$('#markSeen')?.addEventListener('click',()=>{localStorage.setItem(`ritmo:seen:${state.data.profile.id}`,JSON.stringify(notifications().map(n=>n.id)));renderApp(false)});", "$('#markSeen')?.addEventListener('click',()=>saveSettings({seen_notifications:notifications().map(n=>n.id)},'Avisos marcados como vistos.'));", 'mark seen cloud')

# Cabeçalho: no mobile, sino só no topo fixo perto do perfil; desktop mantém um único sino no cabeçalho.
a=s.find("function head(title,sub,action='')"); b=s.find('\nfunction pageHtml()',a)
if a<0 or b<0: raise SystemExit('head não encontrado')
s=s[:a]+"function head(title,sub,action=''){const bell=state.page!=='notifications'&&innerWidth>760?`<button class=\"icon-btn head-notif\" data-page=\"notifications\">${ic('bell',19)}${unreadCount()?`<span class=\"bell-badge\">${unreadCount()}</span>`:''}</button>`:'';return `<div class=\"page-head\"><div><span class=\"eyebrow\">RITMO</span><h1>${title}</h1><p>${sub}</p></div><div class=\"head-actions\">${bell}${action}</div></div>`}"+s[b:]

rep("function pageHtml(){return `<section class=\"page active\">${({home:homePage,income:incomePage,expenses:expensesPage,debts:debtsPage,goals:goalsPage,calendar:calendarPage,insights:insightsPage,notifications:notificationsPage,settings:settingsPage,profile:profilePage}[state.page]||homePage)()}</section>`}","function pageHtml(){return `<section class=\"page active\">${({home:homePage,income:incomePage,expenses:expensesPage,debts:debtsPage,goals:goalsPage,calendar:calendarPage,insights:insightsPage,notifications:notificationsPage,settings:settingsPage,profile:profilePage,more:morePage,shortcuts:shortcutsPage}[state.page]||homePage)()}</section>`}",'router')
rep('<span class="row-icon">${ic(type===','<span class="row-icon ${type}-tone">${ic(type===','row tone')

# Troca funções de lista por versões filtráveis.
def fn(name,nextname,code):
 global s
 a=s.find('function '+name+'('); b=s.find('\nfunction '+nextname+'(',a)
 if a<0 or b<0: raise SystemExit('função não encontrada: '+name)
 s=s[:a]+code+s[b:]
fn('incomePage','expensePageHeader',"function incomePage(){const items=filterItems(state.data.incomes,'income');return `${head('Entradas','Salário, renda extra e tudo que entra.',listAction('income','income','Nova entrada'))}${filterSummary('income',items)}<div class=\"money-list\">${items.length?items.map(x=>itemMoney(x,'income')).join(''):`<div class=\"empty\">${filterActive('income')?'Nenhuma entrada encontrada nesse período.':'Você ainda não cadastrou nenhuma entrada.'}</div>`}</div>`}")
fn('expensesPage','itemMoney',"function expensesPage(){if(innerWidth<=760&&state.movementTab==='income'){const items=filterItems(state.data.incomes,'income');return `${head('Movimentações','Acompanhe o que entra e sai.',listAction('income','income','Nova entrada'))}${expensePageHeader()}${filterSummary('income',items)}<div class=\"money-list\">${items.length?items.map(x=>itemMoney(x,'income')).join(''):`<div class=\"empty\">${filterActive('income')?'Nenhuma entrada encontrada nesse período.':'Nenhuma entrada cadastrada.'}</div>`}</div>`}const items=filterItems(state.data.expenses,'expense');return `${head(innerWidth<=760?'Movimentações':'Saídas','Despesas pagas, pendentes e vencimentos.',listAction('expense','expense','Nova saída'))}${innerWidth<=760?expensePageHeader():''}${filterSummary('expense',items)}<div class=\"money-list\">${items.length?items.map(x=>itemMoney(x,'expense')).join(''):`<div class=\"empty\">${filterActive('expense')?'Nenhuma saída encontrada nesse período.':'Você ainda não cadastrou nenhuma saída.'}</div>`}</div>`}")
fn('debtsPage','debtCard',"function debtsPage(){const items=filterItems(state.data.debts,'debt');return `${head('Dívidas','Acompanhe o total, pagamentos e haveres.',listAction('debt','debt','Nova dívida'))}${filterSummary('debt',items)}<div class=\"big-card-grid\">${items.length?items.map(debtCard).join(''):`<div class=\"empty\">${filterActive('debt')?'Nenhuma dívida encontrada nesse período.':'Nenhuma dívida cadastrada. Quando precisar, ela aparece aqui com o saldo sendo abatido automaticamente.'}</div>`}</div>`}")
fn('goalsPage','goalCard',"function goalsPage(){const items=filterItems(state.data.goals,'goal');return `${head('Metas','Transforme planos em progresso visível.',listAction('goal','goal','Nova meta'))}${filterSummary('goal',items)}<div class=\"big-card-grid\">${items.length?items.map(goalCard).join(''):`<div class=\"empty\">${filterActive('goal')?'Nenhuma meta encontrada nesse período.':'Crie sua primeira meta: viagem, carro, estudos ou reserva de emergência.'}</div>`}</div>`}")

# Menu Mais completo + editor dos atalhos.
more=r'''
function morePage(){return `${head('Mais','Tudo que complementa seu Ritmo, organizado em um só lugar.')}<div class="more-sections"><section class="more-section"><h3>Organização</h3><div class="more-grid"><button class="more-card" data-page="calendar"><span class="more-icon calendar-tone">${ic('calendar',22)}</span><div><strong>Calendário</strong><small>Movimentações e vencimentos por dia.</small></div>${ic('chev',16)}</button><button class="more-card" data-page="insights"><span class="more-icon insight-tone">${ic('spark',22)}</span><div><strong>Insights</strong><small>Veja o que seus dados financeiros mostram.</small></div>${ic('chev',16)}</button><button class="more-card" data-page="shortcuts"><span class="more-icon shortcut-tone">${ic('menu',22)}</span><div><strong>Personalizar atalhos</strong><small>Escolha os três atalhos da barra inferior.</small></div>${ic('chev',16)}</button></div></section><section class="more-section"><h3>Sua conta</h3><div class="more-grid"><button class="more-card" data-page="profile"><span class="more-icon">${ic('user',22)}</span><div><strong>Editar perfil</strong><small>Nome, usuário e senha em um só lugar.</small></div>${ic('chev',16)}</button><button class="more-card" data-settings-open="security"><span class="more-icon security-tone">${ic('shield',22)}</span><div><strong>Segurança</strong><small>Biometria, passkey e bloqueio do aplicativo.</small></div>${ic('chev',16)}</button><button class="more-card" data-page="settings"><span class="more-icon settings-tone">${ic('gear',22)}</span><div><strong>Configurações</strong><small>Aparência e preferências do Ritmo.</small></div>${ic('chev',16)}</button></div></section><section class="more-section"><h3>Ritmo</h3><div class="more-grid"><button class="more-card" data-settings-open="about"><span class="more-icon info-tone">${ic('info',22)}</span><div><strong>Sobre o Ritmo</strong><small>Versão e informações do aplicativo.</small></div>${ic('chev',16)}</button><a class="more-card" href="https://wa.me/5574998029574?text=Ol%C3%A1%20Fl%C3%A1vio%2C%20eu%20gostaria%20de%20suporte%20no%20Ritmo." target="_blank" rel="noopener"><span class="more-icon support-tone">${ic('message',22)}</span><div><strong>Suporte Rocha Tech</strong><small>Fale diretamente pelo WhatsApp.</small></div>${ic('chev',16)}</a></div></section></div>`}
function shortcutsPage(){const selected=mobileShortcutKeys();return `${head('Personalizar atalhos','Escolha três atalhos para deixar sempre à mão.')}<div class="panel shortcuts-panel"><div class="shortcut-preview">${mobileBottom().map(n=>`<div class="preview-item tone-${n[0]}">${ic(n[2],20)}<span>${n[1]}</span></div>`).join('')}</div><p class="shortcut-help">Início e Mais ficam fixos. Selecione exatamente três opções para as posições do meio.</p><div class="shortcut-options">${Object.values(shortcutCatalog).map(n=>`<button type="button" class="shortcut-option ${selected.includes(n[0])?'selected':''}" data-shortcut-option="${n[0]}"><span class="setting-icon tone-${n[0]}">${ic(n[2],18)}</span><div><strong>${n[1]}</strong><small>${selected.includes(n[0])?`Posição ${selected.indexOf(n[0])+1}`:'Toque para adicionar'}</small></div><span class="shortcut-check">${selected.includes(n[0])?ic('check',18):''}</span></button>`).join('')}</div><button class="btn btn-primary shortcut-save" id="saveShortcuts" type="button">Salvar atalhos</button></div>`}
'''
