rep("function modalHtml(){const m=state.modal;if(m.type==='quick')","function modalHtml(){const m=state.modal;if(m.type==='filter')return filterModalHtml(m.filterType);if(m.type==='quick')",'modal filter')

# Eventos de novos recursos.
anchor="  $$('[data-new]').forEach(b=>b.onclick=()=>{state.modal={type:b.dataset.new};renderApp(false)});"
extra=r'''  $$('[data-filter]').forEach(b=>b.onclick=()=>{state.modal={type:'filter',filterType:b.dataset.filter};renderApp(false)});$$('[data-filter-clear]').forEach(b=>b.onclick=()=>{state.filters[b.dataset.filter]=defaultFilter();renderApp(false)});$$('[data-settings-open]').forEach(b=>b.onclick=()=>{state.page='settings';state.settingsSub=b.dataset.settingsOpen;renderApp()});$$('[data-shortcut-option]').forEach(b=>b.onclick=()=>{const k=b.dataset.shortcutOption;let a=mobileShortcutKeys();if(a.includes(k))a=a.filter(x=>x!==k);else if(a.length<3)a.push(k);else return toast('Escolha no máximo três atalhos.');state.data.settings.mobile_shortcuts=a;renderApp(false)});$('#saveShortcuts')?.addEventListener('click',()=>{const a=mobileShortcutKeys();if(a.length!==3)return toast('Escolha três atalhos.');saveSettings({mobile_shortcuts:a},'Atalhos salvos na sua conta.');});$$('[data-filter-days]').forEach(b=>b.onclick=()=>{const days=Number(b.dataset.filterDays),end=new Date(),start=new Date();end.setHours(12,0,0,0);start.setHours(12,0,0,0);start.setDate(start.getDate()-(days-1));const f=getFilter(state.modal.filterType);f.from=dateIsoLocal(start);f.to=dateIsoLocal(end);f.month='';state.filters[state.modal.filterType]=f;renderApp(false)});$('#applyFilter')?.addEventListener('click',()=>{const type=state.modal.filterType,f=getFilter(type);f.month=$('#filterMonth')?.value||'';f.from=$('#filterFrom')?.value||'';f.to=$('#filterTo')?.value||'';f.status=$('#filterStatus')?.value||'all';if(f.from&&f.to&&f.from>f.to)return toast('A data inicial deve vir antes da final.');state.filters[type]=f;state.modal=null;renderApp(false)});$('#clearFilter')?.addEventListener('click',()=>{const type=state.modal.filterType;state.filters[type]=defaultFilter();state.modal=null;renderApp(false)});
'''
rep(anchor,extra+anchor,'bind extras')

# Preferências pequenas: salva nuvem e atualiza memória, sem baixar histórico inteiro.
old="async function saveSettings(patch){try{await api('/api/settings',{method:'PATCH',body:JSON.stringify(patch)});state.data=await api('/api/bootstrap');applyTheme(state.data.settings.theme);renderApp(false);toast('Preferência salva.')}catch(e){toast(e.message)}}"
new="async function saveSettings(patch,msg='Preferência salva.'){try{await api('/api/settings',{method:'PATCH',body:JSON.stringify(patch)});state.data.settings={...state.data.settings,...patch};state.data.profile.data_version=Number(state.data.profile.data_version||0)+1;applyTheme(state.data.settings.theme||'system');renderApp(false);toast(msg)}catch(e){toast(e.message)}}"
