css=cssp.read_text()+r'''

/* Ritmo v6 - filtros, Mais, atalhos e cores semânticas */
.head-filter-btn.active{color:var(--primary);border-color:color-mix(in srgb,var(--primary) 35%,var(--line));background:color-mix(in srgb,var(--primary) 8%,var(--surface-solid))}.filter-dot{position:absolute;right:5px;top:5px;width:7px;height:7px;border-radius:50%;background:var(--gold);border:1px solid var(--surface-solid)}.filter-summary{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:-3px 0 12px;padding:9px 11px;border-radius:13px;background:color-mix(in srgb,var(--primary) 7%,var(--surface-solid));border:1px solid color-mix(in srgb,var(--primary) 18%,var(--line));font-size:9px;color:var(--muted)}.filter-summary button{border:0;background:none;color:var(--primary);font-weight:800}.filter-section{margin:4px 0 15px}.filter-section>strong{display:block;font-size:11px;margin-bottom:9px}.filter-chips{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.filter-chips button{border:1px solid var(--line);background:var(--surface2);border-radius:12px;min-height:39px;font-size:9px;font-weight:750}.filter-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}.more-sections{display:grid;gap:18px}.more-section h3{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);margin:0 0 8px 3px}.more-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.more-card{min-height:82px;border:1px solid var(--line);background:var(--surface-solid);border-radius:18px;padding:13px;display:grid;grid-template-columns:40px 1fr 16px;gap:10px;align-items:center;text-align:left;text-decoration:none;box-shadow:var(--shadow)}.more-icon{width:40px;height:40px;border-radius:13px;background:var(--surface2);display:grid;place-items:center;color:var(--primary)}.more-card strong{display:block;font-size:11px}.more-card small{display:block;color:var(--muted);font-size:8.5px;line-height:1.4;margin-top:3px}.shortcuts-panel{max-width:720px}.shortcut-preview{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;padding:8px;border-radius:18px;background:var(--surface2);margin-bottom:14px}.preview-item{display:flex;flex-direction:column;align-items:center;gap:5px;font-size:8px;color:var(--muted);padding:8px 2px}.shortcut-help{font-size:10px;color:var(--muted);line-height:1.55}.shortcut-options{display:grid;gap:7px;margin:13px 0}.shortcut-option{width:100%;border:1px solid var(--line);background:var(--surface2);border-radius:15px;padding:10px;display:grid;grid-template-columns:38px 1fr 22px;gap:10px;align-items:center;text-align:left}.shortcut-option.selected{border-color:color-mix(in srgb,var(--primary) 38%,var(--line));background:color-mix(in srgb,var(--primary) 7%,var(--surface2))}.shortcut-option strong{display:block;font-size:11px}.shortcut-option small{display:block;color:var(--muted);font-size:8px;margin-top:2px}.shortcut-check{color:var(--primary)}.shortcut-save{width:100%;margin-top:4px}.income-tone,.tone-income svg{color:var(--green)!important}.expense-tone,.tone-expenses svg{color:var(--coral)!important}.tone-debts svg{color:var(--gold)!important}.tone-goals svg{color:var(--sage)!important}.calendar-tone,.tone-calendar svg{color:var(--primary)!important}.insight-tone,.tone-insights svg{color:#8d78c7!important}.security-tone{color:var(--primary)!important}.support-tone{color:#1ca85a!important}.info-tone{color:var(--gold)!important}.settings-tone,.tone-settings svg{color:var(--muted)!important}.bottom button.active svg{filter:none}.bottom button.active{color:var(--primary)}
@media(max-width:760px){.head-actions .head-notif{display:none}.more-grid{grid-template-columns:1fr}.more-card{min-height:76px}.filter-chips{grid-template-columns:1fr 1fr 1fr}.filter-actions{grid-template-columns:1fr 1fr}.shortcut-preview{margin-left:-4px;margin-right:-4px}.page-head .head-filter-btn{width:44px;height:44px}.page-head .head-filter-btn svg{width:20px;height:20px}}
'''
