# Static shell cache-first. API is never cached. Browser clearing cache only forces a fresh download; account data remains D1.
sw="""const CACHE='ritmo-v2';\nconst CORE=['/','/styles.css','/app.js','/manifest.webmanifest','/icon.svg'];\nself.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting())));\nself.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));\nself.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.pathname.startsWith('/api/'))return;if(CORE.includes(u.pathname)||u.pathname==='/'){e.respondWith(caches.match(e.request).then(cached=>cached||fetch(e.request).then(r=>{const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy));return r})));return}e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)))});\n"""
swp.write_text(sw)
print('Ritmo v6 UI aplicada.')
